// The VTK fixtures (testdata/upstream/vtk, generated by
// dicom-go-validation/scripts/vtk_fixtures.py with VTK 9.6.2) are computed on
// phantoms defined with integer arithmetic; the helpers below rebuild the
// same voxels.

const vtkFixtureDir = "../testdata/upstream/vtk/"

func loadVTKFixture(t *testing.T, name string, into any) {
	t.Helper()
	data, err := os.ReadFile(vtkFixtureDir + name)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, into); err != nil {
		t.Fatal(err)
	}
}

// doubledOffset is twice the offset of index i from the centre of n voxels.
func doubledOffset(i, n int) int { return 2*i - (n - 1) }

type vtkMeshPhantom struct {
	Name        string    `json:"name"`
	Dims        [3]int    `json:"dims"`
	Radius      int       `json:"radius"`
	SemiAxes    [3]int    `json:"semi_axes"`
	Half        int       `json:"half"`
	Label       int       `json:"label"`
	SurfaceNets vtkMesh   `json:"surface_nets"`
	FlyingEdges *vtkMesh  `json:"flying_edges"`
	Analytic    *vtkSolid `json:"analytic"`
}

type vtkMesh struct {
	Triangles int     `json:"triangles"`
	Area      float64 `json:"area"`
	Volume    float64 `json:"volume"`
}

type vtkSolid struct {
	Area   float64 `json:"area"`
	Volume float64 `json:"volume"`
}

// inside mirrors the phantom tests of vtk_fixtures.py.
func (p vtkMeshPhantom) inside(x, y, z int) bool {
	dx, dy, dz := doubledOffset(x, p.Dims[0]), doubledOffset(y, p.Dims[1]), doubledOffset(z, p.Dims[2])
	switch p.Name {
	case "sphere":
		return dx*dx+dy*dy+dz*dz <= 4*p.Radius*p.Radius
	case "ellipsoid":
		a, b, c := 4*p.SemiAxes[0]*p.SemiAxes[0], 4*p.SemiAxes[1]*p.SemiAxes[1], 4*p.SemiAxes[2]*p.SemiAxes[2]
		return dx*dx*b*c+dy*dy*a*c+dz*dz*a*b <= a*b*c
	case "rotated-cube":
		h := 4 * p.Half * p.Half
		return (dx+dy)*(dx+dy) <= 2*h && (dx-dy)*(dx-dy) <= 2*h && dz*dz <= h
	default:
		return vtkLabelmapLabel(x, y, z) == p.Label
	}
}

func vtkLabelmapLabel(x, y, z int) int {
	switch {
	case (x-12)*(x-12)+(y-20)*(y-20)+(z-20)*(z-20) <= 49:
		return 1
	case x >= 24 && x <= 33 && y >= 10 && y <= 29 && z >= 12 && z <= 27:
		return 2
	case (x-18)*(x-18)+(y-7)*(y-7)+(z-20)*(z-20) <= 16:
		return 3
	}
	return 0
}

func (p vtkMeshPhantom) stack() (*Stack, int) {
	stack := &Stack{PixelSpacing: []float64{1, 1}, SliceThickness: 1}
	count := 0
	for z := 0; z < p.Dims[2]; z++ {
		data := make([]byte, p.Dims[0]*p.Dims[1])
		for y := 0; y < p.Dims[1]; y++ {
			for x := 0; x < p.Dims[0]; x++ {
				if p.inside(x, y, z) {
					data[y*p.Dims[0]+x] = 1
					count++
				}
			}
		}
		stack.Frames = append(stack.Frames, volumeTestFrame(p.Dims[1], p.Dims[0], data, z))
	}
	return stack, count
}

func relativeClose(got, want, tolerance float64) bool {
	return math.Abs(got-want) <= tolerance*math.Max(1, math.Abs(want))
}

// TestISOSurfaceMatchesVTKSurfaceNets compares the voxel-face iso-surface
// with VTK's vtkSurfaceNets3D without smoothing, which builds the same
// surface: the triangle count, area and volume (vtkMassProperties) agree,
// and the volume is the voxel count. The smooth vtkFlyingEdges3D baselines
// must stay near the analytic solids.
func TestISOSurfaceMatchesVTKSurfaceNets(t *testing.T) {
	var fixture struct {
		Phantoms []vtkMeshPhantom `json:"phantoms"`
	}
	loadVTKFixture(t, "mesh.json", &fixture)
	if len(fixture.Phantoms) < 6 {
		t.Fatalf("%d phantoms", len(fixture.Phantoms))
	}
	for _, p := range fixture.Phantoms {
		t.Run(p.Name, func(t *testing.T) {
			stack, count := p.stack()
			vol, err := BuildVolume(stack)
			if err != nil {
				t.Fatal(err)
			}
			triangles, err := vol.ISOSurfaceTriangles(0.5)
			if err != nil {
				t.Fatal(err)
			}
			var area, volume float64
			for _, tri := range triangles {
				ab, ac := tri.B.Sub(tri.A), tri.C.Sub(tri.A)
				area += ab.Cross(ac).Length() / 2
				volume += tri.A.Dot(tri.B.Cross(tri.C)) / 6
			}
			volume = math.Abs(volume)
			want := p.SurfaceNets
			if len(triangles) != want.Triangles || !relativeClose(area, want.Area, 1e-9) || !relativeClose(volume, want.Volume, 1e-9) {
				t.Fatalf("%d triangles, area %g, volume %g; vtkSurfaceNets3D %+v", len(triangles), area, volume, want)
			}
			if !relativeClose(volume, float64(count), 1e-9) {
				t.Fatalf("volume %g, %d voxels", volume, count)
			}
			if p.Analytic != nil && !relativeClose(volume, p.Analytic.Volume, 0.04) {
				t.Fatalf("volume %g, analytic %g", volume, p.Analytic.Volume)
			}
			if smooth := p.FlyingEdges; smooth != nil {
				if !relativeClose(smooth.Volume, p.Analytic.Volume, 0.02) {
					t.Fatalf("vtkFlyingEdges3D volume %g, analytic %g", smooth.Volume, p.Analytic.Volume)
				}
				if p.Analytic.Area > 0 && !relativeClose(smooth.Area, p.Analytic.Area, 0.01) {
					t.Fatalf("vtkFlyingEdges3D area %g, analytic %g", smooth.Area, p.Analytic.Area)
				}
			}
		})
	}
}

// vtkResliceFixture holds reslice.json and slab.json: a 16-bit volume and
// the VTK samples of it.
type vtkResliceFixture struct {
	Dims    [3]int       `json:"dims"`
	Values  []int        `json:"values"`
	Points  [][3]float64 `json:"points"`
	Nearest []float64    `json:"nearest"`
	Linear  []float64    `json:"linear"`
	Cubic   []float64    `json:"cubic"`
	Cases   []struct {
		Center    int       `json:"center"`
		Thickness int       `json:"thickness"`
		Mode      string    `json:"mode"`
		Values    []float64 `json:"values"`
	} `json:"cases"`
}

func (f vtkResliceFixture) stack() *Stack {
	nx, ny, nz := f.Dims[0], f.Dims[1], f.Dims[2]
	stack := &Stack{PixelSpacing: []float64{1, 1}, SliceThickness: 1}
	for z := 0; z < nz; z++ {
		data := make([]byte, nx*ny*2)
		for i := 0; i < nx*ny; i++ {
			binary.LittleEndian.PutUint16(data[2*i:], uint16(int16(f.Values[z*nx*ny+i])))
		}
		frame := volumeTestFrame(ny, nx, data, z)
		frame.Metadata.BitsAllocated, frame.Metadata.BitsStored, frame.Metadata.HighBit, frame.Metadata.PixelRepresentation = 16, 16, 15, 1
		stack.Frames = append(stack.Frames, frame)
	}
	return stack
}

// TestTrilinearSamplesMatchVTK compares VolumeReader.TrilinearAt and
// SampleAt (nearest, linear, cubic) with vtkImageInterpolator (clamp border)
// at interior, edge and corner points. VTK's floor
// (vtkInterpolationMath::Floor, 64-bit build) rounds the coordinate to 16
// fraction bits, so the points are quantized the same way and the samples
// must then agree to rounding.
func TestTrilinearSamplesMatchVTK(t *testing.T) {
	var fixture vtkResliceFixture
	loadVTKFixture(t, "reslice.json", &fixture)
	vol, err := BuildVolume(fixture.stack())
	if err != nil {
		t.Fatal(err)
	}
	reader, err := vol.AcquireReader()
	if err != nil {
		t.Fatal(err)
	}
	defer reader.Close()
	nx, ny := fixture.Dims[0], fixture.Dims[1]
	voxel := func(x, y, z int) float64 { return float64(fixture.Values[(z*ny+y)*nx+x]) }
	// Adding the bias 1.5*2^36 rounds x to the nearest multiple of 2^-16
	// (the 2^-17 tolerance VTK adds to the bias is lost to that rounding).
	quantize := func(v float64) float64 { return math.RoundToEven(v*65536) / 65536 }
	for i, p := range fixture.Points {
		got, ok := reader.TrilinearAt(Vec3{X: quantize(p[0]), Y: quantize(p[1]), Z: quantize(p[2])})
		if !ok || math.Abs(got-fixture.Linear[i]) > 1e-9 {
			t.Fatalf("point %v: %g (%v), vtkImageInterpolator linear %g", p, got, ok, fixture.Linear[i])
		}
		nearest := voxel(int(math.Round(p[0])), int(math.Round(p[1])), int(math.Round(p[2])))
		if fixture.Nearest[i] != nearest {
			t.Fatalf("point %v: nearest %g, voxel %g", p, fixture.Nearest[i], nearest)
		}
		if p[0] == math.Trunc(p[0]) && p[1] == math.Trunc(p[1]) && p[2] == math.Trunc(p[2]) && fixture.Cubic[i] != nearest {
			t.Fatalf("point %v: cubic %g does not interpolate voxel %g", p, fixture.Cubic[i], nearest)
		}
		q := Vec3{X: quantize(p[0]), Y: quantize(p[1]), Z: quantize(p[2])}
		for _, c := range []struct {
			mode Interpolation
			want float64
		}{{InterpolationNearest, fixture.Nearest[i]}, {InterpolationLinear, fixture.Linear[i]}, {InterpolationCubic, fixture.Cubic[i]}} {
			if got, ok := reader.SampleAt(q, c.mode); !ok || math.Abs(got-c.want) > 1e-9 {
				t.Fatalf("point %v mode %d: %g (%v), vtkImageInterpolator %g", p, c.mode, got, ok, c.want)
			}
		}
	}
}

// TestResampleSmallDimensionsMatchVTK resamples volumes with axes of 2, 3
// and 4 voxels by a scale and translation, where the kernels reach past both
// borders, and compares every mode with vtkImageReslice (clamp border, the
// path VTK 9496ad00e3 fixed for cubic).
func TestResampleSmallDimensionsMatchVTK(t *testing.T) {
	var fixture struct {
		Spacing [3]float64 `json:"spacing"`
		Origin  [3]float64 `json:"origin"`
		Cases   []struct {
			Dims    [3]int    `json:"dims"`
			Values  []int     `json:"values"`
			Mode    string    `json:"mode"`
			Extent  [3]int    `json:"extent"`
			Samples []float64 `json:"samples"`
		} `json:"cases"`
	}
	loadVTKFixture(t, "resample.json", &fixture)
	modes := map[string]Interpolation{"nearest": InterpolationNearest, "linear": InterpolationLinear, "cubic": InterpolationCubic}
	quantize := func(v float64) float64 { return math.RoundToEven(v*65536) / 65536 }
	seen := map[int]bool{}
	for _, c := range fixture.Cases {
		volume := vtkResliceFixture{Dims: c.Dims, Values: c.Values}
		vol, err := BuildVolume(volume.stack())
		if err != nil {
			t.Fatal(err)
		}
		reader, err := vol.AcquireReader()
		if err != nil {
			t.Fatal(err)
		}
		for _, n := range c.Dims {
			seen[n] = true
		}
		i := 0
		for z := 0; z <= c.Extent[2]; z++ {
			for y := 0; y <= c.Extent[1]; y++ {
				for x := 0; x <= c.Extent[0]; x++ {
					p := Vec3{
						X: quantize(fixture.Origin[0] + float64(x)*fixture.Spacing[0]),
						Y: quantize(fixture.Origin[1] + float64(y)*fixture.Spacing[1]),
						Z: quantize(fixture.Origin[2] + float64(z)*fixture.Spacing[2]),
					}
					got, ok := reader.SampleAt(p, modes[c.Mode])
					if !ok || math.Abs(got-c.Samples[i]) > 1e-9 {
						t.Fatalf("dims %v %s at %v: %g (%v), vtkImageReslice %g", c.Dims, c.Mode, p, got, ok, c.Samples[i])
					}
					i++
				}
			}
		}
		if i != len(c.Samples) {
			t.Fatalf("dims %v %s: %d samples, fixture %d", c.Dims, c.Mode, i, len(c.Samples))
		}
		reader.Close()
	}
	if !seen[2] || !seen[3] {
		t.Fatalf("dimensions covered %v", seen)
	}
}

// TestAxialSlabsMatchVTK compares axial thick slabs (MIP, MinIP, mean) with
// vtkImageReslice slab modes over interior slices. The sum baselines, for
// ray-sum work, must equal the mean times the thickness. The volume is the
// one of reslice.json.
func TestAxialSlabsMatchVTK(t *testing.T) {
	var volume, fixture vtkResliceFixture
	loadVTKFixture(t, "reslice.json", &volume)
	loadVTKFixture(t, "slab.json", &fixture)
	if volume.Dims != fixture.Dims {
		t.Fatalf("slab.json dims %v, reslice.json %v", fixture.Dims, volume.Dims)
	}
	stack := volume.stack()
	modes := map[string]SlabMode{"max": SlabMIP, "min": SlabMinIP, "mean": SlabAverage, "sum": SlabSum}
	means := map[[2]int][]float64{}
	for _, c := range fixture.Cases {
		if c.Mode == "mean" {
			means[[2]int{c.Center, c.Thickness}] = c.Values
		}
	}
	nx := fixture.Dims[0]
	for _, c := range fixture.Cases {
		if c.Mode == "sum" {
			mean := means[[2]int{c.Center, c.Thickness}]
			for i, sum := range c.Values {
				if math.Abs(sum-mean[i]*float64(c.Thickness)) > 1e-6 {
					t.Fatalf("sum %g is not %d x mean %g", sum, c.Thickness, mean[i])
				}
			}
		}
		plane, err := RenderScalarSlabWithOptionsContext(context.Background(), stack, MPRPlaneAxial, c.Center, c.Thickness, modes[c.Mode], MPRRenderOptions{})
		if err != nil {
			t.Fatal(err)
		}
		for i, want := range c.Values {
			got, ok := plane.ValueAt(i%nx, i/nx)
			if !ok || math.Abs(got-want) > 1e-9 {
				t.Fatalf("%s slab at %d x%d, pixel %d: %g (%v), vtkImageReslice %g", c.Mode, c.Center, c.Thickness, i, got, ok, want)
			}
		}
	}
}

// TestObliqueSlabSamplingMatchesVTK compares the oblique scalar slab (an
// axial plane on the voxel grid) with vtkImageReslice for Sum, trapezoid
// integration and samples at half the slice spacing (#1009).
func TestObliqueSlabSamplingMatchesVTK(t *testing.T) {
	var volume vtkResliceFixture
	loadVTKFixture(t, "reslice.json", &volume)
	var fixture struct {
		Refined []struct {
			Center        int       `json:"center"`
			Slices        int       `json:"slices"`
			Fraction      float64   `json:"fraction"`
			Mode          string    `json:"mode"`
			Trapezoid     bool      `json:"trapezoid"`
			Interpolation string    `json:"interpolation"`
			Values        []float64 `json:"values"`
		} `json:"refined"`
	}
	loadVTKFixture(t, "slab.json", &fixture)
	vol, err := BuildVolume(volume.stack())
	if err != nil {
		t.Fatal(err)
	}
	nx, ny := volume.Dims[0], volume.Dims[1]
	modes := map[string]SlabMode{"max": SlabMIP, "mean": SlabAverage, "sum": SlabSum}
	interpolations := map[string]Interpolation{"nearestneighbor": InterpolationNearest, "linear": InterpolationLinear}
	if len(fixture.Refined) < 8 {
		t.Fatalf("%d refined cases", len(fixture.Refined))
	}
	for _, c := range fixture.Refined {
		origin := vol.VoxelToPatient(Vec3{Z: float64(c.Center)})
		plane := Plane{
			Origin: origin,
			U:      vol.VoxelToPatient(Vec3{X: float64(nx - 1), Z: float64(c.Center)}).Sub(origin),
			V:      vol.VoxelToPatient(Vec3{Y: float64(ny - 1), Z: float64(c.Center)}).Sub(origin),
		}
		// The slab keeps its thickness in slices; the fraction refines it.
		thickness := int(math.Round(float64(c.Slices-1)*c.Fraction)) + 1
		scalar, err := ResliceObliqueSlabScalarWithOptionsContext(context.Background(), vol, plane, nx, ny, thickness, modes[c.Mode], MPRResliceOptions{
			Interpolation: interpolations[c.Interpolation],
			Slab:          SlabSampling{Trapezoid: c.Trapezoid, SpacingFraction: c.Fraction},
		})
		if err != nil {
			t.Fatal(err)
		}
		for i, want := range c.Values {
			got, ok := scalar.ValueAt(i%nx, i/nx)
			if !ok || math.Abs(got-want) > 1e-6 {
				t.Fatalf("%s trapezoid %v fraction %v: pixel %d = %g (%v), vtkImageReslice %g", c.Mode, c.Trapezoid, c.Fraction, i, got, ok, want)
			}
		}
	}
	if _, err := ResliceObliqueSlabScalarWithOptionsContext(context.Background(), vol, Plane{U: Vec3{X: 1}, V: Vec3{Y: 1}}, 4, 4, 3, SlabSum, MPRResliceOptions{Slab: SlabSampling{SpacingFraction: 1.5}}); err == nil {
		t.Error("spacing fraction 1.5 accepted")
	}
}
